-- Google AI Studio (Gemini API) provider, additive only: seed rows for provider_models (created by 0029). APPLY BEFORE deploying the code that lists them: a provider_models table that has rows
-- is authoritative, so until these rows exist AI Studio offers no models (rollback = redeploy the previous Worker; the rows are inert for it).
--   Only chat models with a non-zero free quota (Erich's dashboard, 2026-10-26). limits_json = {context,maxTokens,maxOutput,rpm,rpd,tpm,tpd} (free-tier limits, a hint only; tpm = INPUT tokens/min).
--   extra_json: limited (tiny daily quota, flagged, never the default), shortContext (history trimmed to the per-minute token limit), thinking (ask for thought summaries).
--   price_json is NULL = unknown on purpose (the pricing page lists PAID-tier prices; the Open key is the free tier). The key itself is the user's own, stored encrypted by 0027's provider_user_keys.
-- The INSERTs are generated from src/providers/seed.ts (bun scripts/gen-provider-seed.ts aistudio); test/provider-catalog.test.ts fails on drift.
INSERT OR IGNORE INTO provider_models (provider_id, model_id, kind, display_name, capabilities_json, price_json, limits_json, extra_json, enabled, sort, suggested, origin, seed_ref, user_edited, broken, updated_at) VALUES ('aistudio', 'gemini-3.5-flash-lite', 'chat', 'Gemini 3.5 Flash Lite', '{"text":true,"tools":true,"vision":true}', NULL, '{"context":1048576,"maxTokens":16000,"maxOutput":65536,"rpm":15,"rpd":500,"tpm":250000}', '{"thinking":true}', 1, 27, 1, 'seed', '2026-10-26: live 2026-10-26: native streamGenerateContent: tools round trip with thoughtSignature echo + 32x32 PNG answered "Red"; no thought parts seen (not a thinking model by default)', 0, 0, 0);
